import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"कानूनी अनुच्छेद सूची-पत्र","description":"","frontmatter":{},"headers":[],"relativePath":"hi/92-法律条文索引.md","filePath":"hi/92-法律条文索引.md","lastUpdated":1789183869000}'),h={name:"hi/92-法律条文索引.md"};function i(o,t,l,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="कानूनी-अनुच्छेद-सूची-पत्र" tabindex="-1">कानूनी अनुच्छेद सूची-पत्र <a class="header-anchor" href="#कानूनी-अनुच्छेद-सूची-पत्र" aria-label="Permalink to &quot;कानूनी अनुच्छेद सूची-पत्र&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ क्रमांक</td><td>92</td></tr><tr><td>मॉड्यूल</td><td>परिशिष्ट एवं संदर्भ सामग्री</td></tr><tr><td>मुख्य कीवर्ड</td><td>कानून सूची-पत्र, सहजीवी संविधान, श्रम कानून, उपभोक्ता संरक्षण कानून, सहायक कानून</td></tr></tbody></table><h2 id="i-सूची-पत्र-हेतु-टिप्पणी" tabindex="-1">I. सूची-पत्र हेतु टिप्पणी <a class="header-anchor" href="#i-सूची-पत्र-हेतु-टिप्पणी" aria-label="Permalink to &quot;I. सूची-पत्र हेतु टिप्पणी&quot;">​</a></h2><p>यह सूची-पत्र लंगर सहजीवी सभ्यता में वर्तमान में प्रभावी प्रमुख कानूनी दस्तावेज़ों एवं उनके मुख्य अनुच्छेदों को संग्रहीत करता है, कानूनी पदानुक्रम एवं विभाग के अनुसार वर्गीकृत। सूची की परिधि में सहजीवी संविधान, सहजीवी श्रम कानून, उपभोक्ता संरक्षण कानून तथा शिक्षा, चिकित्सा, आवास, पर्यावरण और एकाधिकार-विरोधी पाँच सहायक कानून शामिल हैं। प्रत्येक प्रविष्टि में कानून का नाम, अनुच्छेद क्रमांक एवं अनुच्छेद की मुख्य सामग्री का सार दिया गया है। यह सूची-पत्र एक संदर्भ उपकरण है; कानूनी अनुच्छेदों का पूर्ण पाठ एवं न्यायिक व्याख्याएँ संबंधित कानूनों के आधिकारिक पाठों में देखें।</p><h2 id="ii-सहजीवी-संविधान" tabindex="-1">II. सहजीवी संविधान <a class="header-anchor" href="#ii-सहजीवी-संविधान" aria-label="Permalink to &quot;II. सहजीवी संविधान&quot;">​</a></h2><p>सहजीवी संविधान लंगर सहजीवी सभ्यता का मूल कानून है, जिसकी सर्वोच्च कानूनी शक्ति है, और सहजीवी सभ्यता की औपचारिक स्थापना के समय निर्मित हुआ।</p><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>हेंग-ब्रह्मांड (वानलिंग हेंगमाओ मूल-ब्रह्मांड) को लंगर सहजीवी सभ्यता का शासित क्षेत्र स्थापित करता है; सभ्यता का मूल उद्देश्य दस हजार जातियों का सहजीवन एवं ब्रह्मांड का उन्नयन प्राप्त करना है</td></tr><tr><td>अनुच्छेद 2</td><td>शिकार-विरोध को सभ्यता का मूल रुख स्थापित करता है, किसी भी रूप में शिकारी साधना एवं संसाधन शिकार को प्रतिबंधित करता है</td></tr><tr><td>अनुच्छेद 3</td><td>&quot;भाग्य एवं विकास के चयन का अधिकार सभी प्राणियों को लौटाना&quot; को सभ्यता का मूल विचार स्थापित करता है</td></tr><tr><td>अनुच्छेद 4</td><td>अधिक काम-अधिक लाभ, स्व-विकास, हर किसी के लिए पथ, दस हजार जातियों की साझा प्रगति को सभ्यता की मूल नीतियाँ स्थापित करता है</td></tr><tr><td>अनुच्छेद 5</td><td>तीन सौ मूल साधना प्रणालियों की निःशुल्क खुली प्रणाली स्थापित करता है; कोई भी संगठन या व्यक्ति साधना प्रणालियों के संचरण-अधिकार पर एकाधिकार नहीं कर सकता</td></tr><tr><td>अनुच्छेद 6</td><td>उत्पादन-आधारित अनुबंध तंत्र को मूल संसाधन वितरण प्रणाली स्थापित करता है</td></tr><tr><td>अनुच्छेद 7</td><td>20% सक्रियण-रणनीति को चरणबद्ध राष्ट्रीय लक्ष्य स्थापित करता है</td></tr><tr><td>अनुच्छेद 8</td><td>वास्तविकता-आधार सिद्धांत स्थापित करता है: वास्तविक दुनिया ही एकमात्र वास्तविक दुनिया है, काल्पनिक सेटिंग्स की कोई कानूनी शक्ति नहीं है</td></tr><tr><td>अनुच्छेद 9</td><td>चार-चरणीय उन्नयन-पथ को सभ्यता की दीर्घकालिक विकास रणनीति स्थापित करता है</td></tr><tr><td>अनुच्छेद 10</td><td>दस हजार जातियों की समानता का सिद्धांत स्थापित करता है; सभी जीवन रूप कानून के समक्ष समान हैं</td></tr><tr><td>अनुच्छेद 11</td><td>सहजीवी विकास सिद्धांत स्थापित करता है; व्यक्तिगत विकास अन्य व्यक्तियों या समूहों के विकास-अधिकारों की कीमत पर नहीं होना चाहिए</td></tr><tr><td>अनुच्छेद 12</td><td>अधिक काम-अधिक लाभ सिद्धांत स्थापित करता है; संसाधन वितरण का मुख्य आधार योगदान है</td></tr><tr><td>अनुच्छेद 13</td><td>स्व-विकास सिद्धांत स्थापित करता है; प्रत्येक जीवन के स्वायत्त विकास-चयन अधिकार का सम्मान किया जाता है</td></tr><tr><td>अनुच्छेद 14</td><td>हर किसी के लिए पथ सिद्धांत स्थापित करता है; राज्य का दायित्व है कि प्रत्येक जीवन को मूल विकास-पथ एवं संसाधन गारंटी प्रदान करे</td></tr><tr><td>अनुच्छेद 15</td><td>स्थिरता सिद्धांत स्थापित करता है; सभी विकास को ब्रह्मांड के मूल की स्थिरता का ध्यान रखना चाहिए</td></tr><tr><td>अनुच्छेद 16–25</td><td>सभी प्राणियों के मूल अधिकार निर्धारित करते हैं: विकास-चयन अधिकार, साधना-संसाधन प्राप्ति अधिकार, समान संरक्षण अधिकार, सहजीवन भागीदारी अधिकार, सांस्कृतिक संरक्षण अधिकार, राहत-अपील अधिकार, व्यक्तिगत स्वतंत्रता अधिकार, व्यक्तिगत गरिमा अधिकार, धर्म-स्वतंत्रता अधिकार, अभिव्यक्ति-स्वतंत्रता अधिकार</td></tr><tr><td>अनुच्छेद 26–31</td><td>सभी प्राणियों के मूल कर्तव्य निर्धारित करते हैं: कानून का पालन कर्तव्य, सहजीवी व्यवस्था अनुरक्षण कर्तव्य, श्रम योगदान कर्तव्य, पर्यावरण संरक्षण कर्तव्य, दूसरों के अधिकारों का सम्मान कर्तव्य, नवीन साधकों का मार्गदर्शन कर्तव्य</td></tr><tr><td>अनुच्छेद 32</td><td>लंगर विधान-सभा को सर्वोच्च शक्ति संस्था स्थापित करता है, जो दस हजार जातियों के प्रतिनिधियों से अनुपातिक रूप से बनी है</td></tr><tr><td>अनुच्छेद 33</td><td>सहजीवी कार्यकारी समिति को सर्वोच्च प्रशासनिक संस्था स्थापित करता है</td></tr><tr><td>अनुच्छेद 34</td><td>सहजीवी न्यायालय को सर्वोच्च न्यायिक संस्था स्थापित करता है, जो स्वतंत्र रूप से न्यायिक शक्ति का प्रयोग करती है</td></tr><tr><td>अनुच्छेद 35</td><td>लंगर निगरानी समिति को स्वतंत्र निगरानी संस्था स्थापित करता है</td></tr><tr><td>अनुच्छेद 36</td><td>विधायी प्रक्रिया निर्धारित करता है: विधेयक लंगर विधान-सभा के आधे से अधिक बहुमत से पारित होता है</td></tr><tr><td>अनुच्छेद 37</td><td>संविधान संशोधन प्रक्रिया निर्धारित करता है: लंगर विधान-सभा के दो-तिहाई से अधिक बहुमत से पारित होना और जनमत संग्रह में आधे से अधिक जनता की सहमति आवश्यक है</td></tr><tr><td>अनुच्छेद 38</td><td>संविधान-समीक्षा प्रणाली स्थापित करता है; सहजीवी न्यायालय को संविधान का उल्लंघन करने वाले कानूनों को अमान्य घोषित करने का अधिकार है</td></tr><tr><td>अनुच्छेद 39</td><td>संवैधानिक वाद प्रणाली स्थापित करता है; सभी प्राणी सीधे संविधान के अनुसार वाद दायर कर सकते हैं</td></tr><tr><td>अनुच्छेद 40</td><td>स्थानीय स्वायत्तता प्रणाली निर्धारित करता है; प्रत्येक तारा-क्षेत्र एवं प्रत्येक पटल संविधान के ढाँचे में स्वायत्तता लागू करते हैं</td></tr><tr><td>अनुच्छेद 41</td><td>दस हजार जातियों की गणराज्य प्रणाली स्थापित करता है; सभी जातियाँ सहजीवी सभ्यता में समान हैं और क्षेत्रीय स्वायत्तता लागू करती हैं</td></tr><tr><td>अनुच्छेद 42</td><td>सभ्यता की आर्थिक प्रणाली निर्धारित करता है: उत्पादन-आधारित अनुबंध को आधार बनाकर, अनेक स्वामित्व रूपों का साझा विकास</td></tr><tr><td>अनुच्छेद 43</td><td>साधना-संसाधनों की राज्य-स्वामित्व एवं न्यायसंगत वितरण प्रणाली निर्धारित करता है</td></tr><tr><td>अनुच्छेद 44</td><td>शिक्षा-समानता प्रणाली स्थापित करता है, प्रत्येक जीवन के समान शिक्षा-अधिकार की गारंटी</td></tr><tr><td>अनुच्छेद 45</td><td>सार्वभौमिक चिकित्सा सुरक्षा प्रणाली स्थापित करता है</td></tr><tr><td>अनुच्छेद 46</td><td>आवास सुरक्षा प्रणाली स्थापित करता है, प्रत्येक जीवन के मूल निवास-अधिकार की गारंटी</td></tr><tr><td>अनुच्छेद 47</td><td>अंतर-पटल अंतःक्रिया के मूल सिद्धांत निर्धारित करता है; बिना अनुमति अंतर-पटल भ्रमण प्रतिबंधित है</td></tr><tr><td>अनुच्छेद 48</td><td>निर्धारित करता है कि पुरातात्विक गतिविधियों के वैध उत्पाद केवल अमूर्त ज्ञान एवं सूचना तक सीमित हैं; पदार्थ एवं ऊर्जा की वापसी प्रतिबंधित है</td></tr><tr><td>अनुच्छेद 49</td><td>समय-प्रत्यावर्तन के मूल सिद्धांत निर्धारित करता है; पहले अवलोकन, फिर सीमित हस्तक्षेप का सिद्धांत पालन करना चाहिए</td></tr><tr><td>अनुच्छेद 50</td><td>निर्धारित करता है कि संविधान की व्याख्या का अधिकार सहजीवी न्यायालय का है, और संविधान संशोधन का अधिकार लंगर विधान-सभा का है</td></tr></tbody></table><h2 id="iii-सहजीवी-श्रम-कानून" tabindex="-1">III. सहजीवी श्रम कानून <a class="header-anchor" href="#iii-सहजीवी-श्रम-कानून" aria-label="Permalink to &quot;III. सहजीवी श्रम कानून&quot;">​</a></h2><p>सहजीवी श्रम कानून श्रम संबंधों को विनियमित करने एवं श्रमिकों के अधिकारों की रक्षा करने वाला मूल कानून है, जो सहजीवी संविधान के अनुच्छेद 42 को विधायी आधार बनाकर बना है।</p><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>विधायी उद्देश्य: श्रम संबंधों को विनियमित करना, श्रमिकों के वैध अधिकारों की रक्षा करना, सामंजस्यपूर्ण सहजीवी श्रम संबंधों का निर्माण करना</td></tr><tr><td>अनुच्छेद 2</td><td>प्रयोज्य क्षेत्र: हेंग-ब्रह्मांड में सभी श्रम संबंध, जिनमें भौतिक श्रम, साधना-श्रम एवं रचनात्मक श्रम शामिल हैं</td></tr><tr><td>अनुच्छेद 3</td><td>श्रमिकों की समान रोजगार प्रणाली स्थापित करता है; जाति, लिंग, साधना-स्तर या मूल के आधार पर रोजगार भेदभाव प्रतिबंधित है</td></tr><tr><td>अनुच्छेद 4</td><td>श्रमिकों की स्वतंत्र रोजगार-चयन प्रणाली स्थापित करता है; जबरन श्रम एवं दासता प्रतिबंधित है</td></tr><tr><td>अनुच्छेद 5</td><td>श्रम अनुबंध प्रणाली निर्धारित करता है; श्रम संबंध स्थापित करते समय लिखित श्रम अनुबंध होना चाहिए</td></tr><tr><td>अनुच्छेद 6</td><td>श्रम अनुबंध के अनिवार्य खंड निर्धारित करता है: अनुबंध अवधि, कार्य सामग्री, श्रम पारिश्रमिक, कार्य समय, श्रम संरक्षण, सामाजिक बीमा</td></tr><tr><td>अनुच्छेद 7</td><td>आठ-घंटे कार्य दिवस एवं प्रति सप्ताह चौवालीस घंटे से अधिक न होने वाली कार्य-समय प्रणाली स्थापित करता है</td></tr><tr><td>अनुच्छेद 8</td><td>ओवरटाइम सीमाएँ निर्धारित करता है: दैनिक ओवरटाइम एक घंटे से अधिक नहीं, विशेष परिस्थितियों में तीन घंटे, मासिक छत्तीस घंटे से अधिक नहीं</td></tr><tr><td>अनुच्छेद 9</td><td>ओवरटाइम वेतन मानक निर्धारित करता है: कार्यदिवस ओवरटाइम 1.5 गुना वेतन, विश्राम दिवस ओवरटाइम 2 गुना वेतन, वैधानिक अवकाश ओवरटाइम 3 गुना वेतन</td></tr><tr><td>अनुच्छेद 10</td><td>न्यूनतम वेतन गारंटी प्रणाली स्थापित करता है; न्यूनतम वेतन मानक प्रत्येक तारा-क्षेत्र स्थानीय परिस्थितियों के अनुसार निर्धारित करता है</td></tr><tr><td>अनुच्छेद 11</td><td>वेतन भुगतान प्रणाली निर्धारित करता है: वेतन मासिक रूप से मुद्रा में श्रमिक को व्यक्तिगत रूप से दिया जाए, बिना काटे या बिना कारण विलंबित किए</td></tr><tr><td>अनुच्छेद 12</td><td>अधिक काम-अधिक लाभ वितरण सिद्धांत स्थापित करता है; कार्य-आधारित वितरण को मुख्य रखते हुए, अनेक वितरण विधियों के सह-अस्तित्व वाली वितरण प्रणाली लागू की जाती है</td></tr><tr><td>अनुच्छेद 13</td><td>श्रम सुरक्षा एवं स्वास्थ्य प्रणाली निर्धारित करता है; नियोक्ता को श्रमिकों को मानकों के अनुरूप श्रम सुरक्षा एवं स्वास्थ्य परिस्थितियाँ प्रदान करनी चाहिए</td></tr><tr><td>अनुच्छेद 14</td><td>विशेष समूहों की सुरक्षा निर्धारित करता है: अवयस्क श्रमिकों, महिला श्रमिकों, दिव्यांग श्रमिकों, निम्न-साधना स्तर के श्रमिकों के लिए विशेष श्रम संरक्षण लागू किया जाता है</td></tr><tr><td>अनुच्छेद 15</td><td>व्यावसायिक प्रशिक्षण प्रणाली स्थापित करता है; नियोक्ता का दायित्व है कि श्रमिकों को व्यावसायिक कौशल प्रशिक्षण प्रदान करे</td></tr><tr><td>अनुच्छेद 16</td><td>साधकों के श्रम अधिकार निर्धारित करता है: साधना-श्रम भी इस कानून द्वारा समान रूप से संरक्षित है, साधना-फलों का स्वामित्व अनुबंध द्वारा तय होता है</td></tr><tr><td>अनुच्छेद 17</td><td>श्रमिकों की सामाजिक बीमा प्रणाली स्थापित करता है: वृद्धावस्था बीमा, चिकित्सा बीमा, बेरोजगारी बीमा, कार्य-चोट बीमा, मातृत्व बीमा</td></tr><tr><td>अनुच्छेद 18</td><td>श्रमिक कल्याण प्रणाली निर्धारित करता है: नियोक्ता को श्रमिकों को आवश्यक कल्याण सुविधाएँ प्रदान करनी चाहिए</td></tr><tr><td>अनुच्छेद 19</td><td>श्रम विवाद समाधान प्रणाली स्थापित करता है: वार्ता, मध्यस्थता, पंचाट, वाद चार-स्तरीय समाधान तंत्र</td></tr><tr><td>अनुच्छेद 20</td><td>ट्रेड यूनियन प्रणाली निर्धारित करता है; श्रमिकों को अपने वैध अधिकारों की रक्षा हेतु कानून के अनुसार ट्रेड यूनियन बनाने एवं उसमें शामिल होने का अधिकार है</td></tr><tr><td>अनुच्छेद 21</td><td>सामूहिक अनुबंध प्रणाली निर्धारित करता है; ट्रेड यूनियन श्रमिकों का प्रतिनिधित्व कर नियोक्ता के साथ सामूहिक अनुबंध करती है</td></tr><tr><td>अनुच्छेद 22</td><td>निर्धारित करता है कि नियोक्ता के आंतरिक नियम श्रमिक प्रतिनिधि सभा या सभी श्रमिकों की चर्चा से पारित होने चाहिए</td></tr><tr><td>अनुच्छेद 23</td><td>श्रम अनुबंध समाप्ति की शर्तें एवं प्रक्रिया निर्धारित करता है</td></tr><tr><td>अनुच्छेद 24</td><td>आर्थिक क्षतिपूर्ति प्रणाली निर्धारित करता है; नियोक्ता को कानूनी रूप से श्रम अनुबंध समाप्त करने पर आर्थिक क्षतिपूर्ति देनी होगी</td></tr><tr><td>अनुच्छेद 25</td><td>अवैध रूप से श्रम अनुबंध समाप्त करने की क्षतिपूर्ति प्रणाली निर्धारित करता है</td></tr><tr><td>अनुच्छेद 26</td><td>श्रम प्रेषण प्रबंधन प्रणाली स्थापित करता है, श्रम प्रेषण रोजगार को विनियमित करता है</td></tr><tr><td>अनुच्छेद 27</td><td>अंशकालिक रोजगार के विशेष नियम निर्धारित करता है</td></tr><tr><td>अनुच्छेद 28</td><td>निरीक्षण-जाँच प्रणाली निर्धारित करता है; श्रम प्रशासनिक विभाग कानून के अनुसार नियोक्ताओं के श्रम कानूनों के पालन की निगरानी एवं जाँच करते हैं</td></tr><tr><td>अनुच्छेद 29</td><td>कानूनी दायित्व निर्धारित करता है: इस कानून का उल्लंघन करने वाले नियोक्ता कानून के अनुसार प्रशासनिक, नागरिक एवं आपराधिक दायित्व वहन करेंगे</td></tr><tr><td>अनुच्छेद 30</td><td>इस कानून की प्रभावी तिथि एवं व्याख्या-अधिकार निर्धारित करता है</td></tr></tbody></table><h2 id="iv-उपभोक्ता-संरक्षण-कानून" tabindex="-1">IV. उपभोक्ता संरक्षण कानून <a class="header-anchor" href="#iv-उपभोक्ता-संरक्षण-कानून" aria-label="Permalink to &quot;IV. उपभोक्ता संरक्षण कानून&quot;">​</a></h2><p>उपभोक्ता संरक्षण कानून उपभोक्ताओं के वैध अधिकारों की रक्षा करने एवं व्यापारिक संचालकों के आचरण को विनियमित करने वाला मूल कानून है।</p><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>विधायी उद्देश्य: उपभोक्ताओं के वैध अधिकारों की रक्षा, सामाजिक आर्थिक व्यवस्था का अनुरक्षण, सहजीवी बाजार अर्थव्यवस्था के स्वस्थ विकास को बढ़ावा</td></tr><tr><td>अनुच्छेद 2</td><td>प्रयोज्य क्षेत्र: हेंग-ब्रह्मांड में उपभोक्ताओं द्वारा दैनिक जीवन की आवश्यकताओं हेतु वस्तुएँ खरीदने, उपयोग करने या सेवाएँ प्राप्त करने के अधिकारों की सुरक्षा</td></tr><tr><td>अनुच्छेद 3</td><td>संचालक एवं उपभोक्ता के बीच लेन-देन के मूल सिद्धांत स्थापित करता है: स्वेच्छा, समानता, निष्पक्षता, सद्भावना</td></tr><tr><td>अनुच्छेद 4</td><td>राज्य द्वारा उपभोक्ताओं के वैध अधिकारों की सुरक्षा का सिद्धांत स्थापित करता है; राज्य उपभोक्ताओं के कानूनी अधिकार-प्रयोग की गारंटी हेतु उपाय करता है</td></tr><tr><td>अनुच्छेद 5</td><td>उपभोक्ताओं के नौ मूल अधिकार निर्धारित करता है: सुरक्षा अधिकार, जानकारी अधिकार, स्व-चयन अधिकार, निष्पक्ष लेन-देन अधिकार, क्षतिपूर्ति अधिकार, संगठन अधिकार, ज्ञान प्राप्ति अधिकार, सम्मान अधिकार, निगरानी अधिकार</td></tr><tr><td>अनुच्छेद 6</td><td>उपभोक्ता सुरक्षा अधिकार निर्धारित करता है: वस्तुएँ खरीदने-उपयोग करने एवं सेवाएँ प्राप्त करने पर उपभोक्ता को व्यक्तिगत एवं संपत्ति सुरक्षा को क्षति न पहुँचने का अधिकार है</td></tr><tr><td>अनुच्छेद 7</td><td>उपभोक्ता जानकारी अधिकार निर्धारित करता है: उपभोक्ता को खरीदी-उपयोग की गई वस्तुओं या प्राप्त सेवाओं की वास्तविक स्थिति जानने का अधिकार है</td></tr><tr><td>अनुच्छेद 8</td><td>उपभोक्ता स्व-चयन अधिकार निर्धारित करता है: उपभोक्ता को वस्तुओं या सेवाओं के स्वतंत्र चयन का अधिकार है</td></tr><tr><td>अनुच्छेद 9</td><td>उपभोक्ता निष्पक्ष लेन-देन अधिकार निर्धारित करता है: उपभोक्ता को निष्पक्ष लेन-देन का अधिकार है, जबरन लेन-देन अस्वीकार करने का अधिकार है</td></tr><tr><td>अनुच्छेद 10</td><td>उपभोक्ता क्षतिपूर्ति अधिकार निर्धारित करता है: वस्तुओं की खरीद-उपयोग या सेवाओं से व्यक्तिगत या संपत्ति क्षति उठाने वाले उपभोक्ता को कानून के अनुसार क्षतिपूर्ति पाने का अधिकार है</td></tr><tr><td>अनुच्छेद 11</td><td>संचालकों के मूल कर्तव्य निर्धारित करता है: वैधानिक एवं अनुबंधित कर्तव्यों का पालन, निगरानी स्वीकार, सुरक्षा सुनिश्चित, वास्तविक जानकारी प्रदान, रसीद जारी, गुणवत्ता गारंटी, तीन-गारंटी पालन, अनुचित लेन-देन न करना, गरिमा का उल्लंघन न करना</td></tr><tr><td>अनुच्छेद 12</td><td>संचालक की सुरक्षा-गारंटी दायित्व निर्धारित करता है: संचालक को यह सुनिश्चित करना चाहिए कि प्रदत्त वस्तुएँ या सेवाएँ व्यक्तिगत एवं संपत्ति सुरक्षा की आवश्यकताओं को पूरा करें</td></tr><tr><td>अनुच्छेद 13</td><td>संचालक की सूचना-प्रकटीकरण दायित्व निर्धारित करता है: संचालक को उपभोक्ताओं को वस्तुओं या सेवाओं की वास्तविक जानकारी देनी चाहिए, झूठा या भ्रामक प्रचार नहीं करना चाहिए</td></tr><tr><td>अनुच्छेद 14</td><td>साधना उत्पादों एवं सेवाओं के विशेष विनियम निर्धारित करता है: साधना-विधियों, साधना-यंत्रों, ऊर्जा उत्पादों के संचालकों के पास विशेष योग्यता होनी चाहिए, उत्पादों को सुरक्षा प्रमाणन पारित करना चाहिए</td></tr><tr><td>अनुच्छेद 15</td><td>मानक खंडों का विनियमन निर्धारित करता है: संचालक मानक खंडों द्वारा उपभोक्ता अधिकारों को बाहर या सीमित नहीं कर सकते, न ही संचालक दायित्व को घटा या माफ कर सकते हैं</td></tr><tr><td>अनुच्छेद 16</td><td>सात-दिन बिना-कारण वापसी प्रणाली निर्धारित करता है: नेटवर्क जैसे दूरस्थ तरीकों से वस्तुएँ खरीदने वाले उपभोक्ता को प्राप्ति तिथि से सात दिनों के भीतर वस्तुएँ लौटाने का अधिकार है</td></tr><tr><td>अनुच्छेद 17</td><td>तीन-गारंटी प्रणाली निर्धारित करता है: संचालक द्वारा प्रदत्त वस्तुएँ या सेवाएँ गुणवत्ता आवश्यकताओं को पूरा न करने पर उपभोक्ता राष्ट्रीय विनियमों के अनुसार मरम्मत, बदलाव या वापसी माँग सकता है</td></tr><tr><td>अनुच्छेद 18</td><td>दंडात्मक क्षतिपूर्ति प्रणाली निर्धारित करता है: संचालक द्वारा वस्तुओं या सेवाओं में धोखाधड़ी करने पर, उपभोक्ता की माँग के अनुसार हुई क्षति की क्षतिपूर्ति बढ़ाई जाएगी, बढ़ी हुई राशि उपभोक्ता द्वारा खरीदी गई वस्तुओं के मूल्य या प्राप्त सेवाओं के व्यय का तीन गुना है</td></tr><tr><td>अनुच्छेद 19</td><td>उपभोक्ता संगठन निर्धारित करता है: उपभोक्ता संघ एवं अन्य उपभोक्ता संगठन कानूनी रूप से स्थापित सामाजिक संगठन हैं जो वस्तुओं एवं सेवाओं पर सामाजिक निगरानी करते हैं और उपभोक्ताओं के वैध अधिकारों की रक्षा करते हैं</td></tr><tr><td>अनुच्छेद 20</td><td>उपभोक्ता विवाद समाधान मार्ग निर्धारित करता है: संचालक से वार्ता-समाधान, उपभोक्ता संघ से मध्यस्थता का अनुरोध, संबंधित प्रशासनिक विभाग में शिकायत, पंचाट के लिए प्रस्तुति, न्यायालय में वाद दायर</td></tr><tr><td>अनुच्छेद 21</td><td>विवादों में साक्ष्य-भार उत्क्रमण निर्धारित करता है: टिकाऊ वस्तुओं या सजावट जैसी सेवाओं के लिए, उपभोक्ता को प्राप्ति से छह माह के भीतर दोष मिलने पर साक्ष्य-भार संचालक का होगा</td></tr><tr><td>अनुच्छेद 22</td><td>संचालकों का प्रशासनिक एवं आपराधिक दायित्व निर्धारित करता है</td></tr><tr><td>अनुच्छेद 23</td><td>इस कानून की प्रभावी तिथि एवं व्याख्या-अधिकार निर्धारित करता है</td></tr></tbody></table><h2 id="v-पाँच-सहायक-कानून" tabindex="-1">V. पाँच सहायक कानून <a class="header-anchor" href="#v-पाँच-सहायक-कानून" aria-label="Permalink to &quot;V. पाँच सहायक कानून&quot;">​</a></h2><h3 id="_5-1-शिक्षा-गारंटी-कानून" tabindex="-1">5.1 शिक्षा गारंटी कानून <a class="header-anchor" href="#_5-1-शिक्षा-गारंटी-कानून" aria-label="Permalink to &quot;5.1 शिक्षा गारंटी कानून&quot;">​</a></h3><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>विधायी उद्देश्य: सभी प्राणियों के समान शिक्षा-अधिकार की गारंटी, सहजीवी शिक्षा प्रणाली का निर्माण, दस हजार जातियों की संस्कृतियों के साझा विकास को बढ़ावा</td></tr><tr><td>अनुच्छेद 2–5</td><td>शिक्षा-समानता सिद्धांत, निःशुल्क शिक्षा सिद्धांत (मूल शिक्षा चरण में), शिक्षा-विविधता सिद्धांत, शिक्षा-नवाचार सिद्धांत स्थापित करते हैं</td></tr><tr><td>अनुच्छेद 6–10</td><td>पूर्व-विद्यालय शिक्षा, अनिवार्य शिक्षा, उच्च माध्यमिक शिक्षा, उच्च शिक्षा, साधना-शिक्षा की प्रणाली-संरचना निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 11–15</td><td>साधना-शिक्षा की विशेष प्रणालियाँ निर्धारित करते हैं: तीन सौ प्रणालियों के शिक्षण विनियम, गुरु प्रणाली, साधना-संसाधन आवंटन प्रणाली</td></tr><tr><td>अनुच्छेद 16–20</td><td>शिक्षकों के अधिकार-कर्तव्य, शिक्षक योग्यता प्रणाली, शिक्षक वेतन-गारंटी निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 21–25</td><td>शिक्षा निवेश गारंटी, शिक्षा सुविधा निर्माण, शिक्षा सूचनाकरण, विशेष शिक्षा, अंतर-जातीय शिक्षा निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 26–30</td><td>शिक्षा मूल्यांकन प्रणाली, शिक्षा निगरानी प्रणाली, कानूनी दायित्व एवं परिशिष्ट निर्धारित करते हैं</td></tr></tbody></table><h3 id="_5-2-चिकित्सा-सुरक्षा-कानून" tabindex="-1">5.2 चिकित्सा सुरक्षा कानून <a class="header-anchor" href="#_5-2-चिकित्सा-सुरक्षा-कानून" aria-label="Permalink to &quot;5.2 चिकित्सा सुरक्षा कानून&quot;">​</a></h3><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>विधायी उद्देश्य: सार्वभौमिक चिकित्सा सुरक्षा प्रणाली स्थापित करना, सभी प्राणियों के स्वास्थ्य-अधिकार की गारंटी, दस हजार जातियों के समग्र स्वास्थ्य स्तर में वृद्धि</td></tr><tr><td>अनुच्छेद 2–5</td><td>सार्वभौमिक चिकित्सा बीमा सिद्धांत, मूल चिकित्सा निःशुल्क सिद्धांत, चीनी-पश्चिमी चिकित्सा संयोजन सिद्धांत, साधना-चिकित्सा समावेशन सिद्धांत स्थापित करते हैं</td></tr><tr><td>अनुच्छेद 6–10</td><td>मूल चिकित्सा बीमा, गंभीर रोग बीमा, चिकित्सा सहायता, वाणिज्यिक स्वास्थ्य बीमा की बहुस्तरीय चिकित्सा बीमा प्रणाली निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 11–15</td><td>चिकित्सा संस्थान प्रबंधन, चिकित्सकीय कर्मी प्रणाली, चिकित्सा गुणवत्ता-सुरक्षा, साधना-चिकित्सा के विशेष विनियम निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 16–20</td><td>औषधि प्रबंधन, चिकित्सा उपकरण प्रबंधन, ऊर्जा चिकित्सा उत्पाद प्रबंधन, मूल औषधि प्रणाली निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 21–25</td><td>सार्वजनिक स्वास्थ्य प्रणाली, रोग निवारण-नियंत्रण, स्वास्थ्य शिक्षा, अंतर-जातीय चिकित्सा, विशेष समूह चिकित्सा सुरक्षा निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 26–30</td><td>चिकित्सा विवाद समाधान, चिकित्सा निगरानी, कानूनी दायित्व एवं परिशिष्ट निर्धारित करते हैं</td></tr></tbody></table><h3 id="_5-3-आवास-सुरक्षा-कानून" tabindex="-1">5.3 आवास सुरक्षा कानून <a class="header-anchor" href="#_5-3-आवास-सुरक्षा-कानून" aria-label="Permalink to &quot;5.3 आवास सुरक्षा कानून&quot;">​</a></h3><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>विधायी उद्देश्य: सभी प्राणियों के मूल निवास-अधिकार की गारंटी, बहुस्तरीय आवास सुरक्षा प्रणाली का निर्माण, सबके लिए आवास की प्राप्ति</td></tr><tr><td>अनुच्छेद 2–5</td><td>निवास-अधिकार गारंटी सिद्धांत, आवास समानता सिद्धांत, किराया-खरीद दोनों सिद्धांत, सतत आवास सिद्धांत स्थापित करते हैं</td></tr><tr><td>अनुच्छेद 6–10</td><td>सार्वजनिक किराये आवास, सुरक्षा किराये आवास, साझा स्वामित्व आवास, वाणिज्यिक आवास की आपूर्ति प्रणाली निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 11–15</td><td>आवास भविष्य निधि प्रणाली, आवास सब्सिडी प्रणाली, प्रथम-गृह सहायता नीति, साधकों के लिए विशेष आवास नीति निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 16–20</td><td>आवास निर्माण मानक, आवास में स्थान-तकनीक का अनुप्रयोग, हरित भवन, वृद्ध-अनुकूल एवं बाधा-रहित आवास निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 21–25</td><td>रियल एस्टेट बाजार नियंत्रण, किराया बाजार विनियम, संपत्ति सेवा प्रबंधन, आवास मरम्मत गारंटी निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 26–30</td><td>आवास सुरक्षा निगरानी, कानूनी दायित्व एवं परिशिष्ट निर्धारित करते हैं</td></tr></tbody></table><h3 id="_5-4-पर्यावरण-संरक्षण-कानून" tabindex="-1">5.4 पर्यावरण संरक्षण कानून <a class="header-anchor" href="#_5-4-पर्यावरण-संरक्षण-कानून" aria-label="Permalink to &quot;5.4 पर्यावरण संरक्षण कानून&quot;">​</a></h3><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>विधायी उद्देश्य: पर्यावरण की सुरक्षा एवं सुधार, प्रदूषण एवं अन्य सार्वजनिक हानियों की रोकथाम-नियंत्रण, जन स्वास्थ्य की गारंटी, ब्रह्मांडीय पारिस्थितिक सभ्यता निर्माण को बढ़ावा, सतत विकास को आगे बढ़ाना</td></tr><tr><td>अनुच्छेद 2–5</td><td>संरक्षण-प्राथमिकता सिद्धांत, रोकथाम-प्रधान सिद्धांत, समग्र उपचार सिद्धांत, जन-भागीदारी सिद्धांत, क्षति-दायित्व सिद्धांत स्थापित करते हैं</td></tr><tr><td>अनुच्छेद 6–10</td><td>पर्यावरण निगरानी-प्रबंधन प्रणाली, पर्यावरण मानक प्रणाली, पर्यावरण प्रभाव मूल्यांकन प्रणाली, पर्यावरण निगरानी प्रणाली, अंतर-पटल पर्यावरण प्रबंधन निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 11–15</td><td>वायु प्रदूषण निवारण, जल प्रदूषण निवारण, मृदा प्रदूषण निवारण, ऊर्जा प्रदूषण निवारण, नियम-प्रदूषण निवारण निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 16–20</td><td>ठोस अपशिष्ट उपचार, ध्वनि प्रदूषण निवारण, रेडियोधर्मी प्रदूषण निवारण, पारिस्थितिक संरक्षण, जैव-विविधता संरक्षण निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 21–25</td><td>साधना गतिविधियों का पर्यावरणीय प्रभाव नियंत्रण, ऊर्जा खनन की पारिस्थितिक संरक्षण, अंतर-पटल पुरातत्व की पर्यावरणीय आवश्यकताएँ निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 26–30</td><td>सूचना प्रकटीकरण एवं जन भागीदारी, पर्यावरण सार्वजनिक हित वाद, कानूनी दायित्व एवं परिशिष्ट निर्धारित करते हैं</td></tr></tbody></table><h3 id="_5-5-एकाधिकार-विरोधी-कानून" tabindex="-1">5.5 एकाधिकार-विरोधी कानून <a class="header-anchor" href="#_5-5-एकाधिकार-विरोधी-कानून" aria-label="Permalink to &quot;5.5 एकाधिकार-विरोधी कानून&quot;">​</a></h3><table tabindex="0"><thead><tr><th>अनुच्छेद क्रमांक</th><th>मुख्य सामग्री</th></tr></thead><tbody><tr><td>अनुच्छेद 1</td><td>विधायी उद्देश्य: एकाधिकारिक आचरण की रोकथाम-निषेध, बाजार निष्पक्ष प्रतिस्पर्धा की सुरक्षा, आर्थिक संचालन दक्षता में वृद्धि, उपभोक्ता हितों एवं सामाजिक सार्वजनिक हितों का संरक्षण, सहजीवी बाजार अर्थव्यवस्था के स्वस्थ विकास को बढ़ावा</td></tr><tr><td>अनुच्छेद 2–5</td><td>प्रतिस्पर्धा नीति की आधारभूत स्थिति, निष्पक्ष प्रतिस्पर्धा समीक्षा प्रणाली, एकाधिकार समझौतों का निषेध, बाजार प्रभुत्व स्थिति के दुरुपयोग का निषेध, उद्यम एकाग्रता का नियंत्रण स्थापित करते हैं</td></tr><tr><td>अनुच्छेद 6–10</td><td>एकाधिकार समझौतों की पहचान एवं छूट, क्षैतिज एकाधिकार समझौते, ऊर्ध्वाधर एकाधिकार समझौते, उद्योग संघों के एकाधिकारिक आचरण निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 11–15</td><td>बाजार प्रभुत्व स्थिति की पहचान, प्रभुत्व स्थिति के दुरुपयोग के आचरण-प्रकार, शिकारी मूल्य-निर्धारण का निषेध निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 16–20</td><td>उद्यम एकाग्रता घोषणा मानक, समीक्षा प्रक्रिया, अतिरिक्त प्रतिबंधात्मक शर्तें, एकाग्रता निषेध के निर्णय निर्धारित करते हैं</td></tr><tr><td>अनुच्छेद 21–25</td><td>साधना प्रणालियों में एकाधिकार का विशेष निषेध निर्धारित करते हैं: साधना-विधियों का एकाधिकार निषेध, साधना-संसाधन एकाधिकार निषेध, गुरु-नेटवर्क एकाधिकार निषेध</td></tr><tr><td>अनुच्छेद 26–30</td><td>एकाधिकार-विरोधी प्रवर्तन संस्था, जाँच प्रक्रिया, कानूनी दायित्व, क्षमा प्रणाली एवं परिशिष्ट निर्धारित करते हैं</td></tr></tbody></table><h2 id="उपसंहार" tabindex="-1">उपसंहार <a class="header-anchor" href="#उपसंहार" aria-label="Permalink to &quot;उपसंहार&quot;">​</a></h2><p>कानूनी अनुच्छेद सूची-पत्र लंगर सहजीवी सभ्यता की विधि-व्यवस्था का संदर्भ मानचित्र है। मूल कानून के रूप में सहजीवी संविधान से, जन-जीवन को विनियमित करने वाले श्रम कानून एवं उपभोक्ता संरक्षण कानून तक, और फिर पाँच सहायक कानूनों तक, ये मिलकर &quot;संविधान को नायक, मूल कानूनों को रीढ़ और सहायक कानूनों को आधार बनाने वाली&quot; पूर्ण कानूनी प्रणाली का निर्माण करते हैं। यह प्रणाली सुनिश्चित करती है कि सहजीवी सभ्यता की सभी गतिविधियाँ विधि-शासन की पटरी पर चलें, और दस हजार जातियों की साझा प्रगति के लिए ठोस संस्थागत गारंटी प्रदान करे।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>41-共生劳动法 (सहजीवी श्रम कानून)</li><li>48-司法体系与裁决机制 (न्यायिक प्रणाली और निर्णय-तंत्र)</li></ul>',28)])])}const u=d(h,[["render",i]]);export{_ as __pageData,u as default};
